<?php
namespace Modules\StockTransferNew\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\StockTransferNew\Entities\StockTransfer;use Modules\StockTransferNew\Services\StockTransferWorkflowService;use Modules\StockTransferNew\Utilities\StockTransferTenant;
class ApprovalController extends Controller{public function __construct(protected StockTransferWorkflowService $workflow){}public function index(){$transfers=StockTransfer::where('business_id',StockTransferTenant::businessId())->where('status','pending_approval')->latest()->paginate(25);return view('stocktransfernew::approvals.index',compact('transfers'));}public function approve(Request $request,StockTransfer $transfer){$this->workflow->approve($transfer,$request->input('note'));return back()->with('status','Transfer approved.');}public function reject(Request $request,StockTransfer $transfer){$this->workflow->reject($transfer,$request->input('note'));return back()->with('status','Transfer rejected.');}}
